from __future__ import annotations

from dataclasses import dataclass


SECONDS_PER_DAY = 86_400


def _require(label: str, value: str | None) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip()


@dataclass(frozen=True)
class RecurringPrice:
    price_id: str
    nickname: str
    unit_amount_cents: int
    interval: str

    def __post_init__(self) -> None:
        pid = _require("price_id", self.price_id)
        nick = _require("nickname", self.nickname)
        interval = _require("interval", self.interval)
        if self.unit_amount_cents < 0:
            raise ValueError("unit_amount_cents must be non-negative")
        if interval not in {"month", "year"}:
            raise ValueError("unsupported billing interval")
        object.__setattr__(self, "price_id", pid)
        object.__setattr__(self, "nickname", nick)
        object.__setattr__(self, "interval", interval)


@dataclass(frozen=True)
class SubscriptionBillingPeriod:
    subscription_id: str
    period_start_unix: int
    period_end_unix: int

    def __post_init__(self) -> None:
        sub = _require("subscription_id", self.subscription_id)
        if self.period_end_unix <= self.period_start_unix:
            raise ValueError("period_end_unix must be after period_start_unix")
        object.__setattr__(self, "subscription_id", sub)

    def length_seconds(self) -> int:
        return self.period_end_unix - self.period_start_unix

    def contains(self, moment_unix: int) -> bool:
        return self.period_start_unix <= moment_unix < self.period_end_unix


@dataclass(frozen=True)
class MidCycleUpgradeRequest:
    customer_id: str
    subscription_id: str
    current_price_id: str
    target_price_id: str
    as_of_unix: int
    period: SubscriptionBillingPeriod
    currency: str

    def __post_init__(self) -> None:
        cust = _require("customer_id", self.customer_id)
        sub = _require("subscription_id", self.subscription_id)
        current = _require("current_price_id", self.current_price_id)
        target = _require("target_price_id", self.target_price_id)
        currency = _require("currency", self.currency).lower()
        if len(currency) != 3:
            raise ValueError("currency must be a 3-letter code")
        if not self.period.contains(self.as_of_unix):
            raise ValueError("as_of_unix must fall inside the billing period")
        object.__setattr__(self, "customer_id", cust)
        object.__setattr__(self, "subscription_id", sub)
        object.__setattr__(self, "current_price_id", current)
        object.__setattr__(self, "target_price_id", target)
        object.__setattr__(self, "currency", currency)


def build_saas_catalog() -> dict[str, RecurringPrice]:
    rows = (
        RecurringPrice("price_starter_monthly", "Starter", 2_900, "month"),
        RecurringPrice("price_growth_monthly", "Growth", 9_900, "month"),
        RecurringPrice("price_scale_monthly", "Scale", 24_900, "month"),
    )
    return {row.price_id: row for row in rows}


def lookup_price(catalog: dict[str, RecurringPrice], price_id: str) -> RecurringPrice:
    entry = catalog.get(price_id.strip())
    if entry is None:
        raise ValueError("unknown price_id")
    return entry


def request_summary(request: MidCycleUpgradeRequest) -> str:
    return (
        f"{request.customer_id} {request.subscription_id} "
        f"{request.current_price_id}->{request.target_price_id} "
        f"as_of={request.as_of_unix}"
    )


def money_label(cents: int, currency: str) -> str:
    major = cents / 100
    return f"{major:.2f} {currency.upper()}"


def build_period(
    *,
    subscription_id: str = "sub_demo",
    start_unix: int,
    length_days: int,
) -> SubscriptionBillingPeriod:
    end_unix = start_unix + length_days * SECONDS_PER_DAY
    return SubscriptionBillingPeriod(
        subscription_id=subscription_id,
        period_start_unix=start_unix,
        period_end_unix=end_unix,
    )


def build_upgrade_request(
    *,
    customer_id: str = "cus_demo",
    subscription_id: str = "sub_demo",
    current_price_id: str,
    target_price_id: str,
    period: SubscriptionBillingPeriod,
    as_of_unix: int,
    currency: str = "usd",
) -> MidCycleUpgradeRequest:
    return MidCycleUpgradeRequest(
        customer_id=customer_id,
        subscription_id=subscription_id,
        current_price_id=current_price_id,
        target_price_id=target_price_id,
        as_of_unix=as_of_unix,
        period=period,
        currency=currency,
    )

