from __future__ import annotations

"""Shared time math for Stripe-style proration (exact period boundaries)."""

from billing_period_models import SECONDS_PER_DAY, MidCycleUpgradeRequest, SubscriptionBillingPeriod


def period_length_seconds(period: SubscriptionBillingPeriod) -> int:
    return period.length_seconds()


def remaining_seconds(period: SubscriptionBillingPeriod, as_of_unix: int) -> int:
    if as_of_unix < period.period_start_unix:
        return period.length_seconds()
    if as_of_unix >= period.period_end_unix:
        return 0
    return period.period_end_unix - as_of_unix


def elapsed_seconds(period: SubscriptionBillingPeriod, as_of_unix: int) -> int:
    return max(0, as_of_unix - period.period_start_unix)


def proration_fraction(period: SubscriptionBillingPeriod, as_of_unix: int) -> float:
    total = period_length_seconds(period)
    if total <= 0:
        raise ValueError("invalid period length")
    remaining = remaining_seconds(period, as_of_unix)
    return remaining / total


def unused_credit_cents(unit_amount_cents: int, fraction: float) -> int:
    if unit_amount_cents < 0:
        raise ValueError("unit_amount_cents must be non-negative")
    if fraction < 0 or fraction > 1:
        raise ValueError("fraction out of range")
    return int(round(unit_amount_cents * fraction))


def prorated_charge_cents(unit_amount_cents: int, fraction: float) -> int:
    return unused_credit_cents(unit_amount_cents, fraction)


def immediate_upgrade_amount_cents(
    *,
    old_unit_amount_cents: int,
    new_unit_amount_cents: int,
    fraction: float,
) -> int:
    credit = unused_credit_cents(old_unit_amount_cents, fraction)
    charge = prorated_charge_cents(new_unit_amount_cents, fraction)
    return max(0, charge - credit)


def calendar_days_remaining(period: SubscriptionBillingPeriod, as_of_unix: int) -> int:
    """Whole-day remainder used by some internal estimators (not Stripe-accurate alone)."""
    seconds_left = remaining_seconds(period, as_of_unix)
    if seconds_left <= 0:
        return 0
    # Ceiling partial days so "10 days left" includes the current day slice.
    return (seconds_left + SECONDS_PER_DAY - 1) // SECONDS_PER_DAY


def period_day_count(period: SubscriptionBillingPeriod) -> int:
    return max(1, period.length_seconds() // SECONDS_PER_DAY)


def fraction_from_calendar_days(days_remaining: int, assumed_month_days: int = 30) -> float:
    if days_remaining < 0:
        raise ValueError("days_remaining must be non-negative")
    if assumed_month_days < 1:
        raise ValueError("assumed_month_days must be positive")
    capped = min(days_remaining, assumed_month_days)
    return capped / assumed_month_days


def describe_proration_window(request: MidCycleUpgradeRequest) -> dict[str, object]:
    frac = proration_fraction(request.period, request.as_of_unix)
    return {
        "subscription_id": request.subscription_id,
        "remaining_seconds": remaining_seconds(request.period, request.as_of_unix),
        "period_seconds": period_length_seconds(request.period),
        "proration_fraction": round(frac, 6),
        "calendar_days_remaining": calendar_days_remaining(request.period, request.as_of_unix),
    }

