from __future__ import annotations

"""In-app upgrade estimate shown before the customer confirms."""

from billing_period_models import (
    MidCycleUpgradeRequest,
    RecurringPrice,
    build_saas_catalog,
    lookup_price,
    money_label,
)
from period_proration_math import calendar_days_remaining, fraction_from_calendar_days


def _catalog() -> dict[str, RecurringPrice]:
    return build_saas_catalog()


def quote_upgrade_proration(request: MidCycleUpgradeRequest) -> dict[str, object]:
    catalog = _catalog()
    current = lookup_price(catalog, request.current_price_id)
    target = lookup_price(catalog, request.target_price_id)

    days_left = calendar_days_remaining(request.period, request.as_of_unix)
    fraction = fraction_from_calendar_days(days_left, assumed_month_days=30)

    unused_credit = int(round(current.unit_amount_cents * fraction))
    new_charge = target.unit_amount_cents
    amount_due = max(0, new_charge - unused_credit)

    return {
        "customer_id": request.customer_id,
        "subscription_id": request.subscription_id,
        "quote_amount_cents": amount_due,
        "unused_credit_cents": unused_credit,
        "new_plan_charge_cents": new_charge,
        "currency": request.currency,
        "source": "in_app_quote",
        "display_amount": money_label(amount_due, request.currency),
        "current_price_id": current.price_id,
        "target_price_id": target.price_id,
        "calendar_days_remaining": days_left,
    }


def summarize_quote_batch(quotes: list[dict[str, object]]) -> dict[str, object]:
    total = sum(int(q["quote_amount_cents"]) for q in quotes)
    return {
        "quote_count": len(quotes),
        "total_quoted_cents": total,
        "quotes": quotes,
    }


class InAppQuoteEngine:
    def quote(self, request: MidCycleUpgradeRequest) -> dict[str, object]:
        return quote_upgrade_proration(request)

    def quote_many(self, requests: list[MidCycleUpgradeRequest]) -> dict[str, object]:
        rows = [self.quote(req) for req in requests]
        return summarize_quote_batch(rows)


def quote_uses_list_price_for_upgrade_charge(request: MidCycleUpgradeRequest) -> bool:
    row = quote_upgrade_proration(request)
    catalog = _catalog()
    target = lookup_price(catalog, request.target_price_id)
    return int(row["new_plan_charge_cents"]) == target.unit_amount_cents


def explain_quote_components(request: MidCycleUpgradeRequest) -> dict[str, object]:
    row = quote_upgrade_proration(request)
    return {
        "unused_credit_cents": row["unused_credit_cents"],
        "new_plan_charge_cents": row["new_plan_charge_cents"],
        "quote_amount_cents": row["quote_amount_cents"],
        "calendar_days_remaining": row["calendar_days_remaining"],
    }


def quote_delta_cents(request: MidCycleUpgradeRequest) -> int:
    row = quote_upgrade_proration(request)
    return int(row["quote_amount_cents"])

