from __future__ import annotations

"""Stripe upcoming invoice preview used by finance and the confirmation modal."""

from billing_period_models import (
    MidCycleUpgradeRequest,
    RecurringPrice,
    build_saas_catalog,
    lookup_price,
    money_label,
)
from period_proration_math import (
    describe_proration_window,
    immediate_upgrade_amount_cents,
    proration_fraction,
    prorated_charge_cents,
    unused_credit_cents,
)


def _catalog() -> dict[str, RecurringPrice]:
    return build_saas_catalog()


def preview_upcoming_invoice(request: MidCycleUpgradeRequest) -> dict[str, object]:
    catalog = _catalog()
    current = lookup_price(catalog, request.current_price_id)
    target = lookup_price(catalog, request.target_price_id)

    fraction = proration_fraction(request.period, request.as_of_unix)
    credit = unused_credit_cents(current.unit_amount_cents, fraction)
    charge = prorated_charge_cents(target.unit_amount_cents, fraction)
    amount_due = immediate_upgrade_amount_cents(
        old_unit_amount_cents=current.unit_amount_cents,
        new_unit_amount_cents=target.unit_amount_cents,
        fraction=fraction,
    )
    window = describe_proration_window(request)

    return {
        "customer_id": request.customer_id,
        "subscription_id": request.subscription_id,
        "upcoming_amount_cents": amount_due,
        "unused_credit_cents": credit,
        "new_plan_charge_cents": charge,
        "currency": request.currency,
        "source": "stripe_upcoming_invoice",
        "display_amount": money_label(amount_due, request.currency),
        "current_price_id": current.price_id,
        "target_price_id": target.price_id,
        "proration_fraction": window["proration_fraction"],
        "remaining_seconds": window["remaining_seconds"],
    }


def summarize_preview_batch(previews: list[dict[str, object]]) -> dict[str, object]:
    total = sum(int(row["upcoming_amount_cents"]) for row in previews)
    return {
        "preview_count": len(previews),
        "total_upcoming_cents": total,
        "previews": previews,
    }


class UpcomingInvoicePreviewer:
    def preview(self, request: MidCycleUpgradeRequest) -> dict[str, object]:
        return preview_upcoming_invoice(request)

    def preview_many(self, requests: list[MidCycleUpgradeRequest]) -> dict[str, object]:
        rows = [self.preview(req) for req in requests]
        return summarize_preview_batch(rows)


def preview_delta_vs_quote(
    *,
    quote_amount_cents: int,
    upcoming_amount_cents: int,
) -> dict[str, object]:
    delta = abs(quote_amount_cents - upcoming_amount_cents)
    return {
        "delta_cents": delta,
        "estimates_match": delta == 0,
        "quote_higher": quote_amount_cents > upcoming_amount_cents,
    }

