    def __init__(self) -> None:
        self._history: list[dict[str, object]] = []

    def compare(self, request: MidCycleUpgradeRequest) -> dict[str, object]:
        outcome = compare_upgrade_estimates(request)
        self._history.append(outcome)
        return outcome

    def summarize(self) -> dict[str, object]:
        return summarize_upgrade_comparisons(self._history)

    def history(self) -> list[dict[str, object]]:
        return list(self._history)


def batch_compare_upgrade_estimates(
    requests: list[MidCycleUpgradeRequest],
) -> dict[str, object]:
    comparisons = [compare_upgrade_estimates(req) for req in requests]
    quotes = [row["quote"] for row in comparisons]
    previews = [row["preview"] for row in comparisons]
    summary = summarize_upgrade_comparisons(comparisons)
    return {
        **summary,
        "quote_batch": summarize_quote_batch(quotes),
        "preview_batch": summarize_preview_batch(previews),
    }


def workflow_status(workflow: UpgradeQuoteWorkflow) -> str:
    summary = workflow.summarize()
    if summary["comparison_count"] == 0:
        return "idle"
    if summary["mismatch_count"]:
        return "needs_billing_review"
    return "aligned"


def first_mismatch(workflow: UpgradeQuoteWorkflow) -> dict[str, object] | None:
    for row in workflow.history():
        if not row["estimates_match"]:
            return row
    return None

